<script setup lang="ts">import {ref} from 'vue';import type {User,Run} from '../types/domain';import {useRoute} from '../hooks/useRoute';import {useSnapshots} from '../stores/snapshots';import {useResearch} from '../stores/research';import Layout from '../components/Layout.vue';import Notice from '../components/common/Notice.vue';import Overview from '../pages/Overview.vue';import Sources from '../pages/Sources.vue';import Compare from '../pages/Compare.vue';import Findings from '../pages/Findings.vue';import Plans from '../pages/Plans.vue';import Audit from '../pages/Audit.vue';defineProps<{user:User}>();defineEmits(['logout']);const page=useRoute(),data=useSnapshots(),research=useResearch(),selectedId=ref(0);function select(run:Run){selectedId.value=run.id;location.hash='findings'}</script><template><Layout :user="user" :page="page" @logout="$emit('logout')"><Notice :error="data.state.error||research.state.error"/><Sources v-if="page==='sources'" :snapshots="data.state.snapshots" :features="data.state.features" :user="user" :reload="data.reload"/><Compare v-else-if="page==='compare'" :snapshots="data.state.snapshots" :runs="research.state.runs" :features="data.state.features" :user="user" :reload="research.reload" @select="select"/><Findings v-else-if="page==='findings'" :runs="research.state.runs" :findings="research.state.findings" :selected-id="selectedId" :features="data.state.features" :user="user" :reload="research.reload" @select="select"/><Plans v-else-if="page==='plans'" :plans="research.state.plans" :user="user" :reload="research.reload"/><Audit v-else-if="page==='audit'"/><Overview v-else :snapshots="data.state.snapshots" :runs="research.state.runs" :findings="research.state.findings" :plans="research.state.plans" :features="data.state.features" @select="select"/></Layout></template>
